// Generated by MCSuperMods: copied from msm_runtime's FollowTypesGoal.
package msm_test.entity;

import java.util.EnumSet;
import java.util.List;
import java.util.function.Predicate;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.PathfinderMob;
import net.minecraft.world.entity.ai.goal.Goal;
import net.minecraft.world.entity.player.Player;

/**
 * Follows the nearest living entity whose type matches, within {@code range}, and stops at
 * {@code stopDistance}. Vanilla's {@code FollowMobGoal} only follows mobs of another class and
 * cannot select by type, hence this goal.
 */
public class FollowTypesGoal extends Goal {
    private final PathfinderMob mob;
    private final Predicate<LivingEntity> types;
    private final double speed;
    private final float stopDistance;
    private final float range;
    private LivingEntity leader;
    private int timeToRecalcPath;

    public FollowTypesGoal(PathfinderMob mob, Predicate<LivingEntity> types, double speed, float stopDistance, float range) {
        this.mob = mob;
        this.types = types;
        this.speed = speed;
        this.stopDistance = stopDistance;
        this.range = range;
        setFlags(EnumSet.of(Flag.MOVE, Flag.LOOK));
    }

    private boolean followable(LivingEntity e) {
        return e != mob && e.isAlive() && !(e instanceof Player p && p.isSpectator()) && types.test(e);
    }

    @Override
    public boolean canUse() {
        List<LivingEntity> candidates = mob.level().getEntitiesOfClass(LivingEntity.class, mob.getBoundingBox().inflate(range), this::followable);
        LivingEntity nearest = null;
        double best = Double.MAX_VALUE;
        for (LivingEntity e : candidates) {
            double d = mob.distanceToSqr(e);
            if (d < best && d <= (double) range * range) {
                best = d;
                nearest = e;
            }
        }
        if (nearest == null || best <= (double) stopDistance * stopDistance) {
            return false;
        }
        leader = nearest;
        return true;
    }

    @Override
    public boolean canContinueToUse() {
        if (leader == null || !followable(leader)) {
            return false;
        }
        double d = mob.distanceToSqr(leader);
        return d > (double) stopDistance * stopDistance && d <= (double) range * range;
    }

    @Override
    public void start() {
        timeToRecalcPath = 0;
    }

    @Override
    public void stop() {
        leader = null;
        mob.getNavigation().stop();
    }

    @Override
    public void tick() {
        if (leader == null) {
            return;
        }
        mob.getLookControl().setLookAt(leader, 10.0f, mob.getMaxHeadXRot());
        if (--timeToRecalcPath <= 0) {
            timeToRecalcPath = adjustedTickDelay(10);
            mob.getNavigation().moveTo(leader, speed);
        }
    }
}
